<?php
require_once __DIR__.'/includes/functions.php';
require_once __DIR__.'/includes/statistics.php';
if(!in_array($_SERVER['REQUEST_METHOD'],['GET','HEAD'],true)){http_response_code(405);header('Allow: GET, HEAD');exit;}
try{$filters=near_miss_stats_filters($_GET);}catch(InvalidArgumentException $exception){http_response_code(400);echo '<!doctype html><html lang="ko"><meta charset="utf-8"><p>'.h($exception->getMessage()).'</p><a href="statistics.php">통계로 돌아가기</a></html>';exit;}
$_pageTitle='아차사고 통계';$_nearMissPage='statistics';$_extraStylesheets=['assets/css/statistics.css'];
header('Cache-Control: no-store');
require __DIR__.'/includes/header.php';
try{$stats=near_miss_stats_load(db(),$filters);}catch(Throwable $exception){error_log('Near miss statistics: '.$exception->getMessage());http_response_code(500);echo '<p role="alert">통계를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.</p>';require __DIR__.'/includes/footer.php';exit;}
$summary=$stats['summary'];$statuses=['open'=>'접수','in_progress'=>'조치중','closed'=>'완료'];
$url=static fn(array $changes=[])=>near_miss_stats_url($filters,array_replace(['page'=>1],$changes));
$year=(int)date('Y');
$barPanel=static function(array $rows,?string $filterKey=null,int $printLimit=4)use($summary,$url){
    if(!$rows){echo '<p class="nmstats-empty">해당 조건의 기록이 없습니다.</p>';return;}
    $displayRows=near_miss_stats_top($rows);
    $max=max(array_merge([1],array_map('intval',array_column($displayRows,'total'))));
    foreach($displayRows as $index=>$bar){$count=(int)$bar['total'];$width=min(100,$count/$max*100);$percent=$summary['total']?round($count/$summary['total']*100,1):0;
        $link=$filterKey!==null && empty($bar['combined']) ? $url([$filterKey=>$bar['label']]).'#nmstats-reports' : null; ?>
        <div class="nmstats-bar-row<?= $index >= $printLimit ? ' nmstats-print-hide' : '' ?>"><div class="nmstats-bar-label"><?php if($link): ?><a href="<?= h($link) ?>"><?= h($bar['label']) ?></a><?php else: ?><?= h($bar['label']) ?><?php endif; ?><span><?= number_format($count) ?>건 <small><?= $percent ?>%</small></span></div><div class="nmstats-bar-track"><span style="width:<?= $width ?>%"></span></div></div>
    <?php }
};
?>
<div class="nmstats-heading"><div><p class="nmstats-eyebrow">NEAR MISS · 아차사고 분석</p><h2>아차사고 통계</h2><p>발생일을 기준으로 신고 추이와 위험요인, 조치 현황을 확인합니다.</p></div><div class="nmstats-heading-actions"><button type="button" class="btn btn-primary" onclick="window.print()">통계 인쇄</button><a class="btn" href="index.php">아차사고 목록으로</a></div></div>
<p class="nmstats-print-conditions">조회 기간: <?= h($filters['from']) ?> ~ <?= h($filters['to']) ?> · 소속: <?= h($filters['team'] ?: '전체') ?> · 사고유형: <?= h($filters['risk'] ?: '전체') ?> · 조치상태: <?= h($statuses[$filters['status']] ?? '전체') ?><span>인쇄 요약: 사고유형·소속 상위 4개, 위험요인별 상위 3개</span></p>
<section class="nmstats-filter-panel" aria-label="통계 조회 조건"><form method="get" class="nmstats-filters"><label>시작일<input type="date" name="from" value="<?= h($filters['from']) ?>" required></label><label>종료일<input type="date" name="to" value="<?= h($filters['to']) ?>" required></label><label>소속<select name="team"><option value="">전체 소속</option><?php foreach($stats['teams'] as $team): ?><option value="<?= h($team) ?>" <?= $filters['team']===$team?'selected':'' ?>><?= h($team) ?></option><?php endforeach; ?></select></label><label>사고유형<select name="risk"><option value="">전체 유형</option><?php foreach($stats['risks'] as $risk): ?><option value="<?= h($risk) ?>" <?= $filters['risk']===$risk?'selected':'' ?>><?= h($risk) ?></option><?php endforeach; ?></select></label><label>조치상태<select name="status"><option value="">전체 상태</option><?php foreach($statuses as $code=>$label): ?><option value="<?= $code ?>" <?= $filters['status']===$code?'selected':'' ?>><?= h($label) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary">조회</button></form>
<div class="nmstats-shortcuts"><span>빠른 조회</span><a href="<?= h($url(['from'=>$year.'-01-01','to'=>date('Y-m-d'),'team'=>'','risk'=>'','status'=>''])) ?>">올해</a><a href="<?= h($url(['from'=>($year-1).'-01-01','to'=>($year-1).'-12-31','team'=>'','risk'=>'','status'=>''])) ?>">지난해</a><?php if($stats['bounds']['first_date']): ?><a href="<?= h($url(['from'=>$stats['bounds']['first_date'],'to'=>$stats['bounds']['last_date'],'team'=>'','risk'=>'','status'=>''])) ?>">전체 기간</a><?php endif; ?><span class="nmstats-range"><?= h($filters['from']) ?> ~ <?= h($filters['to']) ?></span></div>
<?php if($filters['team']!==''||$filters['risk']!==''||$filters['status']!==''): ?><p class="nmstats-active-filters">적용 조건: <?= h(implode(' · ',array_filter([$filters['team'],$filters['risk'],$statuses[$filters['status']] ?? '']))) ?> <a href="<?= h($url(['team'=>'','risk'=>'','status'=>''])) ?>">조건 해제</a></p><?php endif; ?></section>
<section class="nmstats-kpis" aria-label="기간 내 아차사고 요약"><article><span>전체 신고</span><strong><?= number_format($summary['total']) ?><small>건</small></strong><p><?= $summary['team_count'] ?>개 소속 · 선택한 기간 기준</p></article><article class="nmstats-closed"><span>조치 완료</span><strong><?= number_format($summary['closed']) ?><small>건</small></strong><p>완료율 <?= $summary['completion_rate'] ?>%</p></article><article class="nmstats-progress"><span>조치중</span><strong><?= number_format($summary['in_progress']) ?><small>건</small></strong><p>상태가 ‘조치중’인 보고서</p></article><article class="nmstats-open"><span>접수</span><strong><?= number_format($summary['open']) ?><small>건</small></strong><p>상태가 ‘접수’인 보고서</p></article></section>
<p class="nmstats-note">조치 현황은 보고서에 저장된 상태를 기준으로 집계합니다. 조치 내용의 입력 여부와는 구분됩니다.</p>
<section class="nmstats-panel"><div class="nmstats-panel-heading"><h3>월별 신고 추이</h3><span>막대를 누르면 해당 월 기록 조회</span></div>
<?php $maxMonthly=max(1,...array_column($stats['months'],'total')); ?><div class="nmstats-month-scroll"><div class="nmstats-month-chart" style="--months:<?= count($stats['months']) ?>"><?php foreach($stats['months'] as $month): $first=max($filters['from'],$month['key'].'-01');$last=min($filters['to'],(new DateTimeImmutable($month['key'].'-01'))->format('Y-m-t')); ?><a class="nmstats-month" href="<?= h($url(['from'=>$first,'to'=>$last])) ?>#nmstats-reports" aria-label="<?= h($month['key']) ?> <?= $month['total'] ?>건 보기"><span class="nmstats-month-count"><?= $month['total'] ?></span><span class="nmstats-month-column"><span style="height:<?= max(1,$month['total']/$maxMonthly*100) ?>%" class="<?= $month['total']===0?'is-zero':'' ?>"></span></span><span class="nmstats-month-label"><?= h($month['label']) ?></span></a><?php endforeach; ?></div></div></section>
<div class="nmstats-grid"><section class="nmstats-panel"><div class="nmstats-panel-heading"><h3>사고유형별 신고</h3><span>유형을 눌러 상세 조회</span></div><?php $barPanel($stats['groups']['risk'],'risk'); ?></section><section class="nmstats-panel"><div class="nmstats-panel-heading"><h3>소속별 신고</h3><span>소속을 눌러 상세 조회</span></div><?php $barPanel($stats['groups']['team'],'team'); ?></section></div>
<section class="nmstats-panel nmstats-factor-panel"><div class="nmstats-panel-heading"><h3>위험요인 분석</h3><span>각 분류별 건수 · 빈 항목은 미분류</span></div><div class="nmstats-tabs" role="tablist" aria-label="위험요인 분류"><?php $factors=['unsafe_state'=>'불안전한 상태','unsafe_action'=>'불안전한 행동','careless_action'=>'부주의한 행동','careless_state'=>'부주의한 상태'];$firstFactor=true;foreach($factors as $key=>$label): ?><button type="button" role="tab" id="tab-<?= $key ?>" aria-controls="factor-<?= $key ?>" aria-selected="<?= $firstFactor?'true':'false' ?>" tabindex="<?= $firstFactor?'0':'-1' ?>"><?= h($label) ?></button><?php $firstFactor=false;endforeach; ?></div><?php $firstFactor=true;foreach($factors as $key=>$label): ?><div class="nmstats-factor" id="factor-<?= $key ?>" role="tabpanel" aria-labelledby="tab-<?= $key ?>" tabindex="0" <?= $firstFactor?'':'hidden' ?>><h4 class="nmstats-print-factor-title"><?= h($label) ?></h4><?php $barPanel($stats['groups'][$key],null,3); ?></div><?php $firstFactor=false;endforeach; ?><p class="nmstats-note">상위 8개 항목과 그 외 합계를 표시합니다. ‘기타: 직접 입력’은 기타로 묶어 집계합니다.</p></section>
<section class="nmstats-panel" id="nmstats-reports"><div class="nmstats-panel-heading"><h3>조회 조건에 해당하는 보고서</h3><span>총 <?= number_format($summary['total']) ?>건 · <?= $stats['page'] ?> / <?= $stats['pages'] ?>페이지</span></div><div class="nmstats-table-scroll"><table class="nmstats-table"><thead><tr><th>발생일</th><th>제목</th><th>소속</th><th>작성자</th><th>사고유형</th><th>조치상태</th></tr></thead><tbody><?php foreach($stats['reports'] as $report): ?><tr><td><?= h(substr($report['incident_at'],0,10)) ?></td><td><a href="view.php?id=<?= (int)$report['id'] ?>"><?= h($report['title']) ?></a><small><?= h($report['location']) ?></small></td><td><?= h($report['team']) ?></td><td><?= h($report['author_name']) ?></td><td><?= h($report['risk']) ?></td><td><span class="nmstats-status <?= h($report['status']) ?>"><?= h($statuses[$report['status']] ?? $report['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$stats['reports']): ?><tr><td colspan="6" class="nmstats-empty">해당 조건의 기록이 없습니다.</td></tr><?php endif; ?></tbody></table></div><?php if($stats['pages']>1): ?><nav class="nmstats-pagination" aria-label="보고서 페이지"><?php if($stats['page']>1): ?><a class="btn btn-sm" href="<?= h($url(['page'=>$stats['page']-1])) ?>#nmstats-reports">이전</a><?php endif; ?><span><?= $stats['page'] ?> / <?= $stats['pages'] ?></span><?php if($stats['page']<$stats['pages']): ?><a class="btn btn-sm" href="<?= h($url(['page'=>$stats['page']+1])) ?>#nmstats-reports">다음</a><?php endif; ?></nav><?php endif; ?></section>
